        Recipe(dishID: "brazil-acaraje", serves: 4, prepMinutes: 50, cookMinutes: 30, difficulty: 3,
               ingredients: [
                   RecipeIngredient(amount: "2 cups", item: "dried black-eyed peas"),
                   RecipeIngredient(amount: "1", item: "white onion, half chopped rough, half minced"),
