        Recipe(dishID: "brazil-picanha", serves: 6, prepMinutes: 10, cookMinutes: 35, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "3 lb", item: "picanha (ask the butcher for top sirloin cap with the fat left on)"),
                   RecipeIngredient(amount: "2 tbsp", item: "coarse salt"),
                   RecipeIngredient(amount: "1 tbsp", item: "vegetable oil"),
                   RecipeIngredient(amount: "1 cup", item: "cassava flour (or coarse dry breadcrumbs)"),
