                   RecipeIngredient(amount: "1 cup", item: "dried shrimp, soaked 10 minutes (or small cooked shrimp)"),
                   RecipeIngredient(amount: "2 cups", item: "watercress (the stand-in for jambu)"),
                   RecipeIngredient(amount: "1/2 tsp", item: "ground sichuan peppercorn (for jambu's tingle)"),
                   RecipeIngredient(amount: "1 tbsp", item: "malagueta pepper sauce (or any hot sauce)"),
