        Recipe(dishID: "brazil-brigadeiro", serves: 8, prepMinutes: 15, cookMinutes: 15, difficulty: 1,
               ingredients: [
                   RecipeIngredient(amount: "1 can (14 oz)", item: "sweetened condensed milk"),
